using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using Vaelith.Docencia2;using Object=UnityEngine.Object;
public static class PARevision3 {
const string O=@"C:/Users/faust/OneDrive/Desktop/VAELITH/PA_Revision3";
static Vector3 W(float x,float y,float z)=>Docencia2InteriorBuilder.PlanToUnityPos(x,y,z);
static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlaying)return;string f=O+"/command.txt";if(!File.Exists(f))return;string cmd=File.ReadAllText(f).Trim();File.Delete(f);try{if(cmd=="inspect")Inspect();else if(cmd=="apply")Apply();}catch(Exception e){File.WriteAllText(O+"/error.txt",e.ToString());Debug.LogException(e);}}
static void Inspect(){var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(scene.name!="Exterior_Docencia2")throw new Exception("Escena incorrecta");EditorSceneManager.SaveScene(scene,O+"/backup/Scene_Live.unity",true);var b=new StringBuilder();b.AppendLine("dirty="+scene.isDirty);if(SceneView.lastActiveSceneView)b.AppendLine("sceneCamera="+SceneView.lastActiveSceneView.camera.transform.position+" / "+SceneView.lastActiveSceneView.camera.transform.forward);var pa=GameObject.Find("PA_Interior").transform;foreach(var zone in pa.Cast<Transform>()){b.AppendLine(zone.name);var f=zone.Find("Mobiliario_PA_SUPUESTO");if(f)foreach(Transform t in f)b.AppendLine("  "+t.name+" @"+t.position);}File.WriteAllText(O+"/inspect.txt",b.ToString());}
static string Fingerprint(GameObject g){return string.Join("\n",g.GetComponentsInChildren<Component>(true).Where(c=>c).Select(c=>EditorJsonUtility.ToJson(c)));}
public static void Apply(){var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(scene.name!="Exterior_Docencia2")throw new Exception("Wrong scene");var pa=GameObject.Find("PA_Interior").transform;var before=scene.GetRootGameObjects().Where(g=>g!=pa.gameObject).ToDictionary(g=>g,g=>Fingerprint(g));Undo.RegisterFullObjectHierarchyUndo(pa.gameObject,"PA letras y bancas revision3");
 var terminal=pa.Find("Pasillo_Cubiculos_Oeste/Mobiliario_PA_SUPUESTO");if(!terminal)throw new Exception("Missing west corridor props");if(!terminal.Find("Letra_T_Barra_F27_NORTE")){foreach(Transform t in terminal){var pos=t.position;float oldZ=(27-pos.x)/(54f/53.92f);pos.x=W(0,0,10.65f-oldZ).x;t.position=pos;t.name+="_NORTE";}}
 var old=pa.Find("Bancas_Verdes_Revision3_SUPUESTO");if(old)Object.DestroyImmediate(old.gameObject);var group=new GameObject("Bancas_Verdes_Revision3_SUPUESTO").transform;group.SetParent(pa,false);
 var template=GameObject.Find("PB_Interior/05_Fase5_Mobiliario_PB").GetComponentsInChildren<Transform>(true).First(t=>t.name.StartsWith("Banca_Oeste_4_Plazas_SUPUESTO_z"));
 // F01 landing, F02/F10/F12 classroom corridors. Exact module count/coordinates remain a proposal.
 float[,] benches={{8.62f,17.1f,-90},{9.85f,34.0f,-90},{9.85f,36.0f,-90},{18.63f,34.0f,90},{18.63f,36.0f,90}};
 for(int i=0;i<5;i++){var g=Object.Instantiate(template.gameObject,group);g.name="Banca_4_Verdes_Foto_"+(i==0?"F01":"F02_F12")+"_"+i+"_SUPUESTO";g.transform.position=W(benches[i,0],3.606f,benches[i,1]);g.transform.rotation=Quaternion.Euler(0,benches[i,2],0);foreach(var t in g.GetComponentsInChildren<Transform>(true)){t.gameObject.layer=30;t.gameObject.isStatic=true;}foreach(var r in g.GetComponentsInChildren<Renderer>(true)){r.renderingLayerMask=17;r.shadowCastingMode=ShadowCastingMode.Off;}}
 Aula8(pa);if(before.Any(k=>Fingerprint(k.Key)!=k.Value))throw new Exception("Protected root changed");Audit(pa);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText(O+"/applied.txt","Letras y mesa trasladadas al extremo norte del pasillo oeste. 5 modulos nuevos de 4 plazas: 20 asientos. PB, exterior, luces y camaras sin cambios. Cantidades y coordenadas de bancas SUPUESTO.\n");Capture(pa);}
static void Aula8(Transform pa){var group=pa.Find("Aula_8/Mobiliario_PA_SUPUESTO");var desks=group.Cast<Transform>().Where(t=>t.name.StartsWith("Pupitre_")).ToArray();for(int i=0;i<desks.Length;i++){int row=i/8,col=i%8,count=Mathf.Min(8,desks.Length-row*8);desks[i].position=W(23.68f+(col-(count-1)/2f)*.8f,3.606f,17.67f+row*1.2f);desks[i].rotation=Quaternion.identity;}var board=group.Find("Pizarron_Pared_Acceso_SUPUESTO");board.position=W(23.68f,3.606f,15.62f);board.rotation=Quaternion.identity;var teacher=group.Find("Escritorio_Profesor_SUPUESTO");teacher.position=W(26.9f,3.606f,16.52f);teacher.rotation=Quaternion.identity;}
static void Audit(Transform pa){var errors=new System.Collections.Generic.HashSet<string>();var colliders=pa.GetComponentsInChildren<Collider>(true).Where(c=>c.GetComponentsInParent<Transform>().Any(t=>t.name=="Bancas_Verdes_Revision3_SUPUESTO"||t.name=="Mobiliario_PA_SUPUESTO")).ToArray();foreach(var d in pa.GetComponentsInChildren<Docencia2PADoor>(true)){var v=d.GetComponent<Renderer>().bounds.center-d.hinge.position;v.y=0;v*=2;for(int a=0;a<=30;a++)for(int k=1;k<=15;k++){var point=d.hinge.position+Vector3.up+(Quaternion.Euler(0,d.inwardAngle*a/30f,0)*v)*k/15f;foreach(var c in colliders)if(c.enabled&&c.gameObject.activeInHierarchy&&(c.ClosestPoint(point)-point).sqrMagnitude<.0004f)errors.Add(d.hinge.parent.name+" / "+c.name);}}File.WriteAllLines(O+"/barrido.txt",errors.Count==0?new[]{"0 interferencias en barrido muestreado de 29 puertas"}:errors.ToArray());if(errors.Count>0)throw new Exception("Door collision: "+string.Join(";",errors));}
static void Capture(Transform pa){var g=new GameObject("TEMP_Revision3_Capture");var c=g.AddComponent<Camera>();c.enabled=false;c.nearClipPlane=.06f;c.farClipPlane=100;c.fieldOfView=66;Shot(c,"Aula8_Frente_Corregido",20,5.2f,21.5f,24,4.8f,15.5f);Shot(c,"Letras_TI_Norte",4.62f,5.1f,4.1f,4.62f,4.9f,.45f);Shot(c,"Bancas_Taller16",14.24f,5.15f,37.6f,9.9f,4.6f,33.8f);Shot(c,"Banca_Desembarque",13.5f,5.15f,20.5f,8.6f,4.6f,17.1f);Object.DestroyImmediate(g);}
static void Shot(Camera c,string name,float x,float y,float z,float tx,float ty,float tz){c.transform.position=W(x,y,z);c.transform.LookAt(W(tx,ty,tz));var rt=new RenderTexture(1500,950,24);c.targetTexture=rt;var prev=RenderTexture.active;c.Render();RenderTexture.active=rt;var tex=new Texture2D(1500,950,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1500,950),0,0);tex.Apply();File.WriteAllBytes(O+"/"+name+".png",tex.EncodeToPNG());c.targetTexture=null;RenderTexture.active=prev;Object.DestroyImmediate(tex);rt.Release();Object.DestroyImmediate(rt);}

}
